-- Public GitHub repositories cited from roadmap topic pages.
-- Links only. The roadmap text stays on roadmap.sh; this table stores the
-- repository URL, the roadmap that cited it, the use case, and the Lightcast
-- skill it belongs to when that skill is one we already teach against.
-- Additive and reversible: drop table public.github_learning_repos.

begin;

create table if not exists public.github_learning_repos (
    id bigint generated always as identity primary key,
    owner text not null,
    name text not null,
    html_url text not null,
    roadmap_slug text not null,
    use_case text not null,
    taxonomy_key text,
    constraint github_learning_repos_use_case
        check (use_case in (
    'role_path',
    'language',
    'framework',
    'data_infrastructure',
    'practice',
    'ai_tooling'
        )),
    constraint github_learning_repos_repo_roadmap
        unique (owner, name, roadmap_slug)
);

comment on table public.github_learning_repos is
    'Repository links cited by a developer roadmap, joined to skills.taxonomy_key when the roadmap is that skill. No roadmap prose.';

create index if not exists github_learning_repos_taxonomy
    on public.github_learning_repos (taxonomy_key)
    where taxonomy_key is not null;

alter table public.github_learning_repos enable row level security;

drop policy if exists "learning repos are readable" on public.github_learning_repos;
create policy "learning repos are readable"
    on public.github_learning_repos for select
    to authenticated
    using (true);

revoke all on public.github_learning_repos from anon, authenticated;
grant select on public.github_learning_repos to authenticated;
grant all on public.github_learning_repos to service_role;

on conflict (owner, name, roadmap_slug) do update
    set html_url = excluded.html_url,
        use_case = excluded.use_case,
        taxonomy_key = excluded.taxonomy_key;

notify pgrst, 'reload schema';

commit;
